import licenses from "./open-source-licenses.json";

/**
 * PE-03: the open-source packages the app, website and backend ship with,
 * for the /licenses page. Generated by `npm run licenses`
 * (scripts/collect-licenses.mjs); never edit the JSON by hand.
 */
export type OpenSourcePackage = {
  name: string;
  version: string | null;
  /** SPDX id the package declares, or null when it couldn't be read. */
  license: string | null;
  /** The package's page on its registry, where the full licence text is. */
  url: string;
};

export const openSourceGroups: { id: string; title: string; packages: OpenSourcePackage[] }[] = [
  { id: "app", title: "Mobile app", packages: licenses.app },
  { id: "website", title: "Website", packages: licenses.website },
  { id: "backend", title: "Backend", packages: licenses.backend },
];
